package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class BigMatrixImpl_operate_TriageGen1Test {

    @Test
    public void testOperate_ValidInput_StandardMatrix() {
        // 2x3 Matrix
        // [ 1, 2, 3 ]
        // [ 4, 5, 6 ]
        BigDecimal[][] data = {
            {new BigDecimal("1"), new BigDecimal("2"), new BigDecimal("3")},
            {new BigDecimal("4"), new BigDecimal("5"), new BigDecimal("6")}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        // Vector of size 3
        BigDecimal[] v = {
            new BigDecimal("1"),
            new BigDecimal("2"),
            new BigDecimal("3")
        };

        // Expected result:
        // Row 0: 1*1 + 2*2 + 3*3 = 1 + 4 + 9 = 14
        // Row 1: 4*1 + 5*2 + 6*3 = 4 + 10 + 18 = 32
        BigDecimal[] expected = {
            new BigDecimal("14"),
            new BigDecimal("32")
        };

        BigDecimal[] result = matrix.operate(v);

        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_ValidInput_SingleElement() {
        // 1x1 Matrix
        BigDecimal[][] data = {
            {new BigDecimal("5")}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);
        BigDecimal[] v = {new BigDecimal("2")};
        BigDecimal[] expected = {new BigDecimal("10")};

        BigDecimal[] result = matrix.operate(v);

        Assert.assertArrayEquals(expected, result);
    }

    @Test
    public void testOperate_ValidInput_WithZeroAndNegative() {
        // 2x2 Matrix
        // [ 0, -1 ]
        // [ 2, -3 ]
        BigDecimal[][] data = {
            {BigDecimal.ZERO, new BigDecimal("-1")},
            {new BigDecimal("2"), new BigDecimal("-3")}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);
        BigDecimal[] v = {new BigDecimal("5"), new BigDecimal("4")};

        // Expected:
        // Row 0: 0*5 + (-1)*4 = -4
        // Row 1: 2*5 + (-3)*4 = 10 - 12 = -2
        BigDecimal[] expected = {
            new BigDecimal("-4"),
            new BigDecimal("-2")
        };

        BigDecimal[] result = matrix.operate(v);

        Assert.assertArrayEquals(expected, result);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testOperate_WrongLength_ThrowsException() {
        // 2x2 Matrix
        BigDecimal[][] data = {
            {BigDecimal.ONE, BigDecimal.ONE},
            {BigDecimal.ONE, BigDecimal.ONE}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        // Vector of size 3 (should be 2)
        BigDecimal[] v = {BigDecimal.ONE, BigDecimal.ONE, BigDecimal.ONE};

        matrix.operate(v);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testOperate_EmptyVector_ThrowsException() {
        // 1x1 Matrix
        BigDecimal[][] data = {{BigDecimal.ONE}};
        BigMatrixImpl matrix = new BigMatrixImpl(data);

        // Vector of size 0
        BigDecimal[] v = new BigDecimal[0];

        matrix.operate(v);
    }

    @Test
    public void testOperate_LargeValues() {
        BigDecimal largeVal1 = new BigDecimal("1000000000000000000");
        BigDecimal largeVal2 = new BigDecimal("2000000000000000000");

        BigDecimal[][] data = {
            {largeVal1, largeVal2}
        };
        BigMatrixImpl matrix = new BigMatrixImpl(data);
        BigDecimal[] v = {new BigDecimal("2"), new BigDecimal("3")};

        // Expected: 1e18 * 2 + 2e18 * 3 = 2e18 + 6e18 = 8e18
        BigDecimal expectedVal = new BigDecimal("8000000000000000000");
        BigDecimal[] result = matrix.operate(v);

        Assert.assertEquals(0, expectedVal.compareTo(result[0]));
    }
}
